mapper.update:
UPDATE consult
SET doctor_id = #{doctorId},
    publish_type = #{publishType},
    is_public = #{isPublic}
WHERE id = #{id}

mapper.select:
SELECT c.id,c.title,c.symptom,c.department_id,c.create_time,d.name as dept_name FROM consult c LEFT JOIN department d ON c.department_id = d.id WHERE c.is_public = 1
AND (d.name LIKE CONCAT('%',#{keyword},'%') OR c.symptom LIKE CONCAT('%',#{keyword},'%'))
ORDER BY c.create_time DESC LIMIT #{offset},#{pageSize}

SELECT c.id,c.title,c.symptom,c.department_id,c.create_time,d.name as dept_name FROM consult c LEFT JOIN department d ON c.department_id = d.id WHERE ( c.is_public = 1 OR (c.is_public = 0 AND c.doctor_id IS NULL) OR (c.is_public = 0 AND c.doctor_id = #{loginDoctorId}) )
AND (d.name LIKE CONCAT('%',#{keyword},'%') OR c.symptom LIKE CONCAT('%',#{keyword},'%'))
ORDER BY CASE WHEN TRIM(d.name) = TRIM(#{deptName}) THEN 0 WHEN d.name IS NULL THEN 1 ELSE 2 END ASC, c.create_time DESC LIMIT #{offset},#{size}

SELECT DISTINCT c.*
FROM consult c
WHERE c.doctor_id = #{doctorId}
  AND c.id NOT IN (
    SELECT DISTINCT consult_id FROM consult_reply WHERE sender_id = #{doctorId}
)
ORDER BY c.create_time DESC

SELECT c.id,c.title,c.symptom,c.department_id,c.create_time,d.name as dept_name,c.is_public FROM consult c LEFT JOIN department d ON c.department_id = d.id
(d.name LIKE CONCAT('%',#{keyword},'%') OR c.symptom LIKE CONCAT('%',#{keyword},'%'))
ORDER BY c.create_time DESC LIMIT #{offset},#{pageSize}
